export const HOMEWORK_VERSION=1;
export const normalize=s=>String(s).toLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
export function words(text){return [...text.matchAll(/[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu)].map(m=>({text:m[0],start:m.index,end:m.index+m[0].length}));}
export function sentences(text){const out=[];for(const m of text.matchAll(/[^.!?]+(?:[.!?]+[”"']?|$)/g)){const left=m[0].search(/\S/),end=m.index+m[0].trimEnd().length;if(left>=0)out.push({start:m.index+left,end,text:text.slice(m.index+left,end)});}return out;}
const safeId=x=>typeof x==='string'&&!['__proto__','constructor','prototype'].includes(x)&&/^[a-zA-Z0-9_-]{1,80}$/.test(x);
const text=x=>typeof x==='string'&&x.trim().length>0;
export function validateHomework(p){const errors=[];if(!p||typeof p!=='object')return ['Choose a homework JSON object.'];if(p.schemaVersion!==1)errors.push('schemaVersion must be 1.');if(!safeId(p.id))errors.push('id must use 1–80 letters, numbers, hyphens or underscores.');if(!text(p.title)||p.title.length>180)errors.push('Add a title of at most 180 characters.');if(!Array.isArray(p.paragraphs)||!p.paragraphs.length||p.paragraphs.length>30)errors.push('Provide 1–30 source paragraphs.');if(!Array.isArray(p.questions)||!p.questions.length||p.questions.length>12)errors.push('Provide 1–12 actual worksheet questions.');if(errors.length)return errors;const ids=new Set(),qids=new Set();for(const [i,a]of (p.paragraphs||[]).entries()){if(!a||typeof a!=='object'){errors.push(`Paragraph ${i+1} must be an object.`);continue;}if(!safeId(a.id)||ids.has(a.id))errors.push(`Paragraph ${i+1}: use a unique ID.`);ids.add(a.id);if(!text(a.text)||a.text.length>12000)errors.push(`Paragraph ${i+1}: original text is required (maximum 12,000 characters).`);const m=a.mainIdea;if(!m||!text(m.prompt)||!Array.isArray(m.choices)||m.choices.length<2||m.choices.length>3||new Set(m.choices).size!==m.choices.length||!m.choices.every(text)||!Number.isInteger(m.answer)||m.answer<0||m.answer>=m.choices.length)errors.push(`Paragraph ${i+1}: provide one main-idea check with 2–3 unique choices and a valid answer index.`);}
for(const [i,q]of (p.questions||[]).entries()){if(!q||typeof q!=='object'){errors.push(`Question ${i+1} must be an object.`);continue;}if(!safeId(q.id)||qids.has(q.id))errors.push(`Question ${i+1}: use a unique source question ID.`);qids.add(q.id);if(!text(q.text))errors.push(`Question ${i+1}: original wording is required.`);if(!Array.isArray(q.keywordGroups)||!q.keywordGroups.length||q.keywordGroups.some(g=>!g||!Array.isArray(g.any)||!g.any.length||!g.any.every(text)))errors.push(`Question ${i+1}: add keywordGroups with accepted words/phrases in any arrays.`);if(!Array.isArray(q.evidence)||!q.evidence.length)errors.push(`Question ${i+1}: review at least one evidence mapping.`);for(const e of Array.isArray(q.evidence)?q.evidence:[]){if(!e||typeof e!=='object'){errors.push(`Question ${i+1}: evidence mapping must be an object.`);continue;}const a=(p.paragraphs||[]).find(a=>a?.id===e.paragraphId),ss=a&&typeof a.text==='string'?sentences(a.text):[],first=ss.findIndex(s=>s.start===e.start),last=ss.findIndex(s=>s.end===e.end);if(!a||!Number.isInteger(e.start)||!Number.isInteger(e.end)||first<0||last<first||last-first>1)errors.push(`Question ${i+1}: evidence must use exact offsets for one or two adjacent full sentences in a known paragraph.`);if(!text(e.explanation))errors.push(`Question ${i+1}: add an evidence explanation.`);}if(!Array.isArray(q.hints)||q.hints.length<3||!q.hints.every(text))errors.push(`Question ${i+1}: add three non-location hint tiers.`);if(q.reflection&&(!Array.isArray(q.reflection.choices)||q.reflection.choices.length<2||q.reflection.choices.length>3||!q.reflection.choices.every(text)||!Number.isInteger(q.reflection.answer)||q.reflection.answer<0||q.reflection.answer>=q.reflection.choices.length||!text(q.reflection.prompt)))errors.push(`Question ${i+1}: invalid reflection choices.`);}
errors.push(...validateExtensions(p));if(p.reviewRequired||p.uncertainties?.length)errors.push('Resolve the flagged transcription/evidence uncertainties before assigning.');if(JSON.stringify(p).length>250000)errors.push('Homework pack exceeds 250 KB.');return errors;}
export function parseHomework(raw){const p=JSON.parse(raw),e=validateHomework(p);if(e.length)throw Error(e.join('\n'));return p;}
export function ensureHomework(data,profile){data.homeworkPacks??={};const p=data.profiles[profile];p.homework??={active:null,assigned:[],cases:{},rewardIds:[]};p.homework.namespace=profile==='ari'?'emberia':'luminara';return p.homework;}
export function assignHomework(data,profile,pack){const errors=validateHomework(pack);if(errors.length)throw Error(errors.join('\n'));const h=ensureHomework(data,profile),existing=data.homeworkPacks[pack.id];if(existing&&JSON.stringify(existing)!==JSON.stringify(pack)&&Object.values(data.profiles).some(p=>p.homework?.cases?.[pack.id]))throw Error('This case has saved work. Use a new pack ID for revised text or evidence so old highlights stay accurate.');data.homeworkPacks[pack.id]=structuredClone(pack);if(!h.assigned.includes(pack.id))h.assigned.push(pack.id);h.active=pack.id;return h;}
export function caseState(h,pack,replay=false){const list=h.cases[pack.id]??=[];if(!list.length||(replay&&list.at(-1).completed))list.push({attempt:list.length,phase:'keywords',mission:0,paragraph:0,visited:[],keywords:{},mainIdeas:{},clues:{},selection:null,evidence:{},hints:{},checks:[],written:{},reflections:{},started:new Date().toISOString(),completed:null});return list.at(-1);}
export function checkKeywords(q,indices){const ws=words(q.text),selected=[...new Set(indices)].filter(i=>Number.isInteger(i)&&ws[i]).sort((a,b)=>a-b),chosen=normalize(selected.map(i=>ws[i].text).join(' ')),matched=q.keywordGroups.filter(g=>g.any.some(t=>(' '+chosen+' ').includes(' '+normalize(t)+' '))),good=selected.filter(i=>q.keywordGroups.some(g=>g.any.some(t=>(' '+normalize(t)+' ').includes(' '+normalize(ws[i].text)+' '))));const broad=selected.length>Math.max(3,Math.ceil(ws.length*.65));return {matched:matched.length,total:q.keywordGroups.length,good,quality:broad?'broad':matched.length===q.keywordGroups.length?'focused':matched.length?'developing':'try-again',reward:matched.length>0&&!broad};}
export function checkEvidence(pack,q,selection){
 if(!selection||!Number.isInteger(selection.start)||!Number.isInteger(selection.end)||selection.end<=selection.start)return null;
 const a=pack.paragraphs.find(p=>p.id===selection.paragraphId);if(!a)return null;
 const ss=sentences(a.text),included=ss.filter(s=>s.end>selection.start&&s.start<selection.end);
 if(!included.length||included.length>2)return null;
 const ws=words(a.text),alignedStart=ws.some(w=>w.start===selection.start)||included[0].start===selection.start,alignedEnd=ws.some(w=>w.end===selection.end)||included.at(-1).end===selection.end;
 if(!alignedStart||!alignedEnd)return null;
 return q.evidence.find(e=>{if(e.paragraphId!==a.id)return false;if(e.start===selection.start&&e.end===selection.end)return true;if(!Number.isInteger(e.quoteStart)||!Number.isInteger(e.quoteEnd))return false;const quote=words(a.text.slice(e.quoteStart,e.quoteEnd));if(!quote.length)return false;return selection.start>=e.start&&selection.end<=e.end&&selection.start<=e.quoteStart+quote[0].start&&selection.end>=e.quoteStart+quote.at(-1).end;})||null;
}
export function evidenceSegments(s,id){
 const saved=s.evidence[id];
 const verified=saved?.segments??(saved?[saved]:[]);
 const list=[...verified,...(s.evidenceClaims?.[id]||[])];
 return list.filter((e,i)=>list.findIndex(x=>x.paragraphId===e.paragraphId&&x.start===e.start&&x.end===e.end)===i);
}
export function claimEvidence(pack,q,s,selection){
 const match=checkEvidence(pack,q,selection);if(!match)return {correct:false,complete:false};
 s.evidenceClaims??={};const claims=s.evidenceClaims[q.id]??=[];
 if(!claims.some(e=>e.paragraphId===selection.paragraphId&&e.start===selection.start&&e.end===selection.end))claims.push({...selection,evidenceIndex:q.evidence.indexOf(match),explanation:match.explanation});
 const groups=q.evidenceGroups||q.evidence.map((_,i)=>[i]);
 const has=i=>claims.some(e=>e.evidenceIndex===i||(e.paragraphId===q.evidence[i].paragraphId&&e.start===q.evidence[i].start&&e.end===q.evidence[i].end));
 const done=groups.find(g=>g.every(has)),best=groups.reduce((a,b)=>b.filter(has).length/b.length>a.filter(has).length/a.length?b:a,groups[0]);
 if(done&&!s.evidence[q.id])s.evidence[q.id]={...claims[0],segments:done.map(i=>({...claims.find(e=>e.evidenceIndex===i||(e.paragraphId===q.evidence[i].paragraphId&&e.start===q.evidence[i].start&&e.end===q.evidence[i].end))})),independent:!s.hints[q.id]&&!s.checks.some(c=>c.question===q.id&&!c.correct),hints:s.hints[q.id]||0};
 return {correct:true,complete:!!done,matched:best.filter(has).length,required:best.length};
}
export function validateExtensions(p){const errors=[];for(const q of p.questions||[]){if(!q||typeof q!=='object')continue;if(q.evidenceGroups!==undefined&&(!Array.isArray(q.evidenceGroups)||!q.evidenceGroups.length||q.evidenceGroups.some(g=>!Array.isArray(g)||!g.length||new Set(g).size!==g.length||g.some(i=>!Number.isInteger(i)||!q.evidence?.[i]))))errors.push(`${q.id}: evidenceGroups must reference nonempty groups of valid evidence indices.`);const a=q.worksheet;if(a!==undefined){if(!a||typeof a!=='object'){errors.push(`${q.id}: worksheet must be an activity object.`);continue;}if(!['multiple_choice','short_answer','diagram_label','true_false'].includes(a.type))errors.push(`${q.id}: unsupported worksheet activity.`);if(['multiple_choice','true_false'].includes(a.type)&&(!Array.isArray(a.choices)||a.choices.length<2||a.choices.length>4||new Set(a.choices).size!==a.choices.length||!a.choices.every(x=>typeof x==='string'&&x.trim())||!Number.isInteger(a.answer)||a.answer<0||a.answer>=a.choices.length))errors.push(`${q.id}: invalid worksheet choices.`);if(a.type==='diagram_label'&&(!Array.isArray(a.choices)||a.choices.length!==4||new Set(a.choices).size!==4||!Array.isArray(a.order)||a.order.length!==4||new Set(a.order).size!==4||a.order.some(i=>!Number.isInteger(i)||i<0||i>=4)))errors.push(`${q.id}: invalid four-layer diagram order.`);}}return errors;}
export function activityRequired(q){return !!q.worksheet&&q.worksheet.type!=='short_answer';}
export function checkActivity(q,s,answer){if(!activityRequired(q)||!s.evidence[q.id])return false;const a=q.worksheet,correct=a.type==='diagram_label'?Array.isArray(answer)&&answer.length===a.order.length&&answer.every((x,i)=>x===a.order[i]):answer===a.answer;s.activities??={};const result=s.activities[q.id]??={initial:correct,attempts:0,correct:false};if(result.correct)return true;result.attempts++;result.correct=correct;result.latest=new Date().toISOString();return correct;}
export function homeworkRate(h,pack,state){return h.active!==pack.id||state.attempt>0?.1:1;}
export function readingReward(p,h,pack,s,key,amount,xp=0){const id=`homework:${h.namespace}:${pack.id}:${s.attempt}:${key}`;if(h.rewardIds.includes(id))return 0;h.rewardIds.push(id);h.rewardDust??=0;const raw=h.rewardDust+amount*homeworkRate(h,pack,s),whole=Math.floor(raw+1e-9),day=new Date().toISOString().slice(0,10);h.rewardDays??={};const coins=Math.max(0,Math.min(whole,200-(h.rewardDays[day]||0)));h.rewardDays[day]=(h.rewardDays[day]||0)+coins;h.rewardDust=raw-whole;p.collection??={wallet:p.crystals||0,spent:0,pets:[],food:{},accessories:[],equipped:null,worlds:{}};p.crystals+=coins;p.collection.wallet+=coins;p.economyEvents??=[];if(coins)p.economyEvents.push({id,kind:'earn',amount:coins,source:'homework',key,packId:pack.id,attempt:s.attempt,at:new Date().toISOString()});const pet=p.collection.pets.find(pet=>pet.id===p.collection.equipped);if(pet)pet.xp=Math.min(6000,pet.xp+Math.floor(xp*(homeworkRate(h,pack,s)===1?1:.2)));return coins;}
